-- Fix Vietnamese full_name mojibake caused by sqlcmd without -f 65001.
-- Seed SQL is UTF-8-correct; applying without code page 65001 stores Latin-1 garbage.
-- Run:
--   sqlcmd -S localhost,1433 -U sa -P <pwd> -C -d SEAL -f 65001 -i fix_vietnamese_name_mojibake.sql
